local FountainMaker = {}
local PRODUCTS = {
    stone_fountain = { name = "Kamniti vodomet", stoneCost = 3, clayCost = 1, time = 5, cost = 60, beauty = 40, prestige = 3, description = "Kamniti vodomet za trg." },
    marble_fountain = { name = "Marmornat vodomet", marbleCost = 2, stoneCost = 1, clayCost = 1, time = 7, cost = 150, beauty = 55, prestige = 6, happiness = 1, description = "Marmornat vodomet za vrtove." },
    bronze_fountain = { name = "Bronast vodomet", bronzeCost = 2, marbleCost = 1, time = 10, cost = 350, beauty = 70, prestige = 12, happiness = 2, description = "Bronast vodomet s kipi." },
    silver_spout_fountain = { name = "Srebrnolivni vodomet", marbleCost = 2, silverCost = 1, bronzeCost = 1, time = 13, cost = 780, beauty = 82, prestige = 20, happiness = 4, description = "Vodomet s srebrnimi curki za plemiče." },
    gold_statue_fountain = { name = "Zlatokipni vodomet", marbleCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, time = 17, cost = 1700, beauty = 92, prestige = 32, happiness = 7, description = "Vodomet z zlatim kipom za visoke plemiče." },
    royal_grand_fountain = { name = "Kraljevski veliki vodomet", marbleCost = 5, goldCost = 2, silverCost = 1, jewelCost = 2, pearlCost = 1, time = 24, cost = 4000, beauty = 100, prestige = 65, happiness = 14, description = "Veliki kraljevski vodomet z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Vodometna delavnica", cost = { gold = 350, wood = 140, stone = 300 }, upkeep = 9, qualityBonus = 5 },
    stone_yard = { name = "Kamnito dvorišče", cost = { gold = 1200, wood = 300, stone = 600, marble = 8 }, upkeep = 30, qualityBonus = 18 },
    casting_foundry = { name = "Livarna", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, bronze = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_fountain_atelier = { name = "Kraljevski atelje vodometov", cost = { gold = 12000, wood = 700, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
FountainMaker.stoneStock = 18; FountainMaker.marbleStock = 12; FountainMaker.clayStock = 10; FountainMaker.bronzeStock = 10; FountainMaker.silverStock = 8; FountainMaker.goldStock = 6; FountainMaker.jewelStock = 6; FountainMaker.pearlStock = 4
FountainMaker.productStock = {}; FountainMaker.buildings = {}; FountainMaker.maker = nil; FountainMaker.activeMaking = {}; FountainMaker.totalProducts = 0; FountainMaker.dayTimer = 0
function FountainMaker.init() FountainMaker.stoneStock=18; FountainMaker.marbleStock=12; FountainMaker.clayStock=10; FountainMaker.bronzeStock=10; FountainMaker.silverStock=8; FountainMaker.goldStock=6; FountainMaker.jewelStock=6; FountainMaker.pearlStock=4; FountainMaker.productStock={}; FountainMaker.buildings={}; FountainMaker.maker=nil; FountainMaker.activeMaking={}; FountainMaker.totalProducts=0; FountainMaker.dayTimer=0; print("[FountainMaker] Royal Fountain Maker System initialized (6 products, 4 buildings)") end
function FountainMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FountainMaker.maker={name=n or ("Vodometar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vodometar najet: %s (spretnost: %d)",FountainMaker.maker.name,s),"success") end; return true end
function FountainMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FountainMaker.build(id) local ok,e=FountainMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FountainMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FountainMaker.getQualityBonus() local b=0; for _,bd in ipairs(FountainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FountainMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and FountainMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and FountainMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.clayCost and FountainMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.bronzeCost and FountainMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and FountainMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FountainMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FountainMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FountainMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FountainMaker.buildings==0 then return false,"Potrebna delavnica" end; if not FountainMaker.maker then return false,"Potreben vodometar" end; return true end
function FountainMaker.make(pt,qty) qty=qty or 1; local ok,e=FountainMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then FountainMaker.stoneStock=FountainMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then FountainMaker.marbleStock=FountainMaker.marbleStock-d.marbleCost*qty end; if d.clayCost then FountainMaker.clayStock=FountainMaker.clayStock-d.clayCost*qty end; if d.bronzeCost then FountainMaker.bronzeStock=FountainMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then FountainMaker.silverStock=FountainMaker.silverStock-d.silverCost*qty end; if d.goldCost then FountainMaker.goldStock=FountainMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FountainMaker.jewelStock=FountainMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FountainMaker.pearlStock=FountainMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FountainMaker.maker then t=math.max(1,t-math.floor(FountainMaker.maker.skill/12)) end; table.insert(FountainMaker.activeMaking,{id="fountain_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FountainMaker.completeMaking(m) local q=1.0+(FountainMaker.getQualityBonus()/100); if FountainMaker.maker then q=q+(FountainMaker.maker.skill/150) end; q=math.min(2.5,q); FountainMaker.productStock[m.productType]=(FountainMaker.productStock[m.productType] or 0)+m.quantity; FountainMaker.totalProducts=FountainMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FountainMaker.maker then FountainMaker.maker.itemsMade=FountainMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FountainMaker.maker.skill=math.min(100,FountainMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vodomet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fountain.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function FountainMaker.update(dt) if not _G.state then return end; FountainMaker.dayTimer=FountainMaker.dayTimer+dt; if FountainMaker.dayTimer>=30 then FountainMaker.dayTimer=0; for i=#FountainMaker.activeMaking,1,-1 do local m=FountainMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FountainMaker.completeMaking(m); table.remove(FountainMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FountainMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FountainMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FountainMaker.getStats() return {stoneStock=FountainMaker.stoneStock,marbleStock=FountainMaker.marbleStock,clayStock=FountainMaker.clayStock,bronzeStock=FountainMaker.bronzeStock,silverStock=FountainMaker.silverStock,goldStock=FountainMaker.goldStock,jewelStock=FountainMaker.jewelStock,pearlStock=FountainMaker.pearlStock,productStock=FountainMaker.productStock,numBuildings=#FountainMaker.buildings,hasMaker=FountainMaker.maker~=nil,makerName=FountainMaker.maker and FountainMaker.maker.name or "—",makerSkill=FountainMaker.maker and FountainMaker.maker.skill or 0,activeMaking=#FountainMaker.activeMaking,totalProducts=FountainMaker.totalProducts} end
return FountainMaker
